from langchain.tools import tool

@tool("square_root")
def tool1(x: float) -> float:
    """Calculate the square root of a number"""
    return x ** 0.5

@tool("square_root", description="Calculate the square root of a number")
def tool2(x: float) -> float:
    return x ** 0.5

for t in (tool1, tool2):
    print(t.name, "|", t.description, "|", t.invoke({"x": 467}))

try:
    @tool
    def no_docs(x: float) -> float:
        return x ** 0.5
except Exception as e:
    print(type(e).__name__, "->", e)

from typing import Dict, Any
from langchain_core.language_models.fake_chat_models import GenericFakeChatModel
from langchain.agents import create_agent
from langchain.messages import AIMessage, HumanMessage
from langchain.tools import tool

class FakeModel(GenericFakeChatModel):
    """Hace de LLM: devuelve respuestas fijas."""
    def bind_tools(self, tools, **kwargs):
        return self

class FakeTavily:
    """Hace de TavilyClient: devuelve un resultado con la misma forma (un dict)."""
    def search(self, query):
        return {"query": query,
                "results": [{"title": "langchain on PyPI",
                             "url": "https://example.com/langchain",
                             "content": "Example result: langchain 1.3.14 is the latest release."}]}

tavily_client = FakeTavily()

@tool
def web_search(query: str) -> Dict[str, Any]:
    """Search the web for information"""
    return tavily_client.search(query)

model = FakeModel(messages=iter([
    AIMessage(content="", tool_calls=[{"name": "web_search",
                                       "args": {"query": "latest langchain release"},
                                       "id": "call_1"}]),
    AIMessage(content="The latest langchain release is 1.3.14."),
]))

agent = create_agent(model=model, tools=[web_search])

response = agent.invoke({"messages": [HumanMessage(content="What is the latest release of langchain?")]})

tool_msg = response["messages"][2]
print(type(tool_msg).__name__, type(tool_msg.content).__name__)
print(tool_msg.content[:120])
print(response["messages"][-1].content)
